'use strict';

// Simple application — improved for security best practices
//
// Required new dependencies (add to package.json):
//   npm install helmet express-rate-limit

const express = require('express');
const helmet  = require('helmet');          // Secure HTTP headers
const rateLimit = require('express-rate-limit'); // Rate limiting

const app = express();

// ─── 1. Security Headers ────────────────────────────────────────────────────
// helmet() sets X-Content-Type-Options, X-Frame-Options, Content-Security-Policy,
// Strict-Transport-Security, and more in one call.
app.use(helmet());

// ─── 2. Parse JSON bodies safely ────────────────────────────────────────────
// Limit payload size to prevent large-body DoS attacks.
app.use(express.json({ limit: '10kb' }));

// ─── 3. Global Rate Limiter ──────────────────────────────────────────────────
// Allows 100 requests per 15 minutes per IP across all routes.
// Adjust windowMs / max to suit your traffic requirements.
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,   // Disable X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ─── 4. Health endpoint ──────────────────────────────────────────────────────
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ─── 5. Users endpoint with input validation ─────────────────────────────────
app.get('/users', (req, res, next) => {
  try {
    // Input validation: reject unexpected query parameters early.
    const ALLOWED_QUERY_PARAMS = new Set(['page', 'limit']);
    const receivedParams = Object.keys(req.query);
    const invalidParams  = receivedParams.filter(p => !ALLOWED_QUERY_PARAMS.has(p));

    if (invalidParams.length > 0) {
      return res.status(400).json({
        error: `Unexpected query parameter(s): ${invalidParams.join(', ')}`,
      });
    }

    // Validate and sanitize pagination parameters.
    const page  = parsePositiveInt(req.query.page,  1);
    const limit = parsePositiveInt(req.query.limit, 10);

    if (!page || !limit) {
      return res.status(400).json({
        error: '`page` and `limit` must be positive integers.',
      });
    }

    // Cap limit to prevent excessive data exposure.
    if (limit > 100) {
      return res.status(400).json({ error: '`limit` may not exceed 100.' });
    }

    // NOTE: In a real app, fetch from a database here using parameterised queries.
    // Never interpolate user input directly into SQL/NoSQL queries.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];

    res.json({ page, limit, total: users.length, data: users });
  } catch (err) {
    // Pass unexpected errors to the global error handler below.
    next(err);
  }
});

// ─── 6. 404 handler ──────────────────────────────────────────────────────────
// Catch requests to undefined routes before they reach the error handler.
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ─── 7. Global error handler ─────────────────────────────────────────────────
// Must have exactly four parameters so Express recognises it as an error handler.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error server-side for debugging.
  console.error('[ERROR]', err);

  // Never leak internal stack traces or error messages to the client.
  res.status(500).json({ error: 'An internal server error occurred.' });
});

// ─── 8. Configurable port ────────────────────────────────────────────────────
// Read port from the environment; fall back to 3000 for local development only.
const PORT = parseInt(process.env.PORT, 10) || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Parse a value as a positive integer.
 * Returns the integer on success, or null if invalid.
 * @param {*}      value
 * @param {number} defaultValue
 * @returns {number|null}
 */
function parsePositiveInt(value, defaultValue) {
  if (value === undefined || value === null || value === '') {
    return defaultValue;
  }
  const parsed = parseInt(value, 10);
  if (Number.isNaN(parsed) || parsed < 1 || String(parsed) !== String(value)) {
    return null; // Signal invalid input
  }
  return parsed;
}

module.exports = app;

