    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Whitelist fields to prevent accidental data leakage
  const safeUsers = users.map(({ id, name, email }) => ({ id, name, email }));
  res.json(safeUsers);
});

