const express = require('express');

// ─── Security middleware (install via npm if not present) ────────────────────
// npm install helmet express-rate-limit
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ─── Security Headers ────────────────────────────────────────────────────────
// helmet sets a suite of protective HTTP headers (X-Content-Type-Options,
// Strict-Transport-Security, X-Frame-Options, etc.) in one call.
app.use(helmet());

// ─── Body Parsing with Size Limit ────────────────────────────────────────────
// Restricting payload size mitigates denial-of-service via large request bodies.
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ─── Rate Limiting ───────────────────────────────────────────────────────────
// Limits each IP to 100 requests per 15-minute window to reduce brute-force
// and DoS risk.
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,    // Disable the deprecated X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ─── Health Check ────────────────────────────────────────────────────────────
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ─── Users Endpoint ──────────────────────────────────────────────────────────
// Inline validation helper: only allow safe integer IDs passed as query params.
function parsePositiveInt(value) {
  const parsed = parseInt(value, 10);
  // Reject NaN, floats-as-strings ('1.5'), and non-positive values.
  return Number.isInteger(parsed) && parsed > 0 && String(parsed) === String(value)
    ? parsed
    : null;
}

// NOTE: In a real app this would come from a database with parameterised queries,
// never via string interpolation.
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

app.get('/users', (req, res) => {
  // Optional ?id= filter demonstrating input validation.
  if (req.query.id !== undefined) {
    const id = parsePositiveInt(req.query.id);

    if (id === null) {
      // 400 Bad Request — never trust client-supplied data.
      return res.status(400).json({ error: 'Invalid id: must be a positive integer.' });
    }

    const user = USERS.find((u) => u.id === id);

    if (!user) {
      // 404 Not Found — avoid leaking whether other IDs exist.
      return res.status(404).json({ error: 'User not found.' });
    }

    return res.json(user);
  }

  res.json(USERS);
});

// ─── 404 Catch-All ───────────────────────────────────────────────────────────
// Must come after all valid routes. Returns JSON (not an HTML stack trace)
// so the API surface stays consistent and no framework internals are exposed.
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ─── Global Error Handler ────────────────────────────────────────────────────
// Express identifies this as an error handler by the four-argument signature.
// It catches any error passed via next(err) or thrown inside async handlers
// wrapped with a try/catch that calls next(err).
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error server-side for diagnostics …
  console.error('[ERROR]', err);

  // … but send only a generic message to the client so internal details
  // (stack traces, file paths, library versions) are never exposed.
  const statusCode = typeof err.status === 'number' ? err.status : 500;
  res.status(statusCode).json({
    error: statusCode === 500 ? 'An unexpected error occurred.' : err.message,
  });
});

// ─── Server Bootstrap ────────────────────────────────────────────────────────
// Read port from the environment so the value is not hardcoded and can be
// changed per deployment without touching source code.
const PORT = process.env.PORT || 3000;

// Only start listening when this file is run directly, not when it is imported
// by a test suite.  This is the standard Node.js idiom.
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

