// Security Middleware
// ---------------------------------------------------------------------------

// Set secure HTTP response headers (XSS protection, clickjacking, MIME sniffing, etc.)
app.use(helmet());

// Parse incoming JSON bodies; enforce a size limit to prevent payload attacks
app.use(express.json({ limit: '10kb' }));

// Parse URL-encoded bodies (e.g., HTML form submissions)
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Apply rate limiting to all requests to mitigate brute-force / DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15-minute window
  max: 100,                  // Max requests per window per IP
  standardHeaders: true,     // Return rate-limit info in `RateLimit-*` headers
  legacyHeaders: false,      // Disable the `X-RateLimit-*` headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // TODO: Replace with a real database query and add authentication/authorization.
  // Field selection ensures sensitive fields are never accidentally included.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  // Basic pagination support — prevents dumping unbounded datasets
  const page  = Math.max(1, parseInt(req.query.page,  10) || 1);
  const limit = Math.min(50, Math.max(1, parseInt(req.query.limit, 10) || 10));
  const start = (page - 1) * limit;
  const paged = users.slice(start, start + limit);

  res.json({
    data:  paged,
    meta: { page, limit, total: users.length },
  });
});

// ---------------------------------------------------------------------------
// 404 Handler — must come after all valid routes
// ---------------------------------------------------------------------------

app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ---------------------------------------------------------------------------
// Global Error Handler — must be defined with exactly four parameters
// ---------------------------------------------------------------------------

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log full error internally (replace with a proper logger in production)
  console.error('[ERROR]', err);

  // Never leak stack traces or internal details to the client
  const statusCode = Number.isInteger(err.status) && err.status >= 400
    ? err.status
    : 500;

  res.status(statusCode).json({
    error: statusCode === 500
      ? 'An unexpected error occurred. Please try again later.'
      : err.message,
  });
});

// ---------------------------------------------------------------------------
// Start Server
// ---------------------------------------------------------------------------

if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

