app.get('/users', (req, res) => {
  // Input validation: reject unexpected query parameters
  const allowedParams = new Set(['page', 'limit']);
  const receivedParams = Object.keys(req.query);
  const invalidParams = receivedParams.filter((p) => !allowedParams.has(p));

  if (invalidParams.length > 0) {
    return res.status(400).json({
      error: `Invalid query parameter(s): ${invalidParams.join(', ')}`,
    });
  }

  // Validate pagination inputs
  const page = parseInt(req.query.page, 10) || 1;
  const limit = parseInt(req.query.limit, 10) || 10;

  if (page < 1 || limit < 1 || limit > 100) {
    return res.status(400).json({
      error: 'page must be >= 1 and limit must be between 1 and 100.',
    });
  }

  // NOTE: In production, fetch from a database; never hardcode user data.
  // Emails are intentionally omitted — serve only what the caller needs.
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];

  res.json({ page, limit, total: users.length, data: users });
});

// ---------------------------------------------------------------------------
// 4. 404 handler — must come after all valid routes
// ---------------------------------------------------------------------------
