/**
 * app.js — Express application with security best practices applied.
 *
 * Key improvements over the original:
 *  - Helmet for secure HTTP headers
 *  - express-rate-limit to prevent abuse
 *  - Input validation with express-validator
 *  - Strict JSON body-size limits
 *  - Centralised error handler (no stack traces leaked to clients)
 *  - Explicit 404 handler for unknown routes
 *  - Port sourced from environment variable with safe fallback
 */

'use strict';

const express = require('express');
const helmet = require('helmet');               // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const { query, validationResult } = require('express-validator'); // Input validation

const app = express();

// ---------------------------------------------------------------------------
// Security middleware
// ---------------------------------------------------------------------------

// Set common security-related HTTP headers (CSP, HSTS, X-Frame-Options, etc.)
app.use(helmet());

// Parse JSON bodies; enforce a strict size limit to prevent payload-flooding
app.use(express.json({ limit: '10kb' }));

// Parse URL-encoded bodies with the same size cap
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// Rate-limit all requests: max 100 per 15-minute window per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,   // Disable the X-RateLimit-* legacy headers
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Returns a simple liveness signal. No sensitive data is exposed.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 *
 * Optional query parameters (all validated and sanitised):
 *   - limit  (integer, 1–100, default 20)
 *   - offset (integer, >= 0, default 0)
 *
 * Input validation rules defend against injection and unexpected values.
 */
app.get(
  '/users',
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('limit must be an integer between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('offset must be a non-negative integer')
      .toInt(),
  ],
  (req, res, next) => {
    // Return 400 with structured errors if validation failed
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // NOTE: Replace with a real database call in production.
    // These values are illustrative only.
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const limit  = req.query.limit  ?? 20;
    const offset = req.query.offset ?? 0;
    const page   = allUsers.slice(offset, offset + limit);

    res.json({ total: allUsers.length, limit, offset, data: page });
  },
);

// ---------------------------------------------------------------------------
// Catch-all 404 handler
// Placed after all valid routes so only truly unknown paths reach it.
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ---------------------------------------------------------------------------
// Centralised error handler
// Express identifies this by its four-parameter signature (err, req, res, next).
// NEVER send err.stack or internal details to the client in production.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error server-side for debugging
  console.error('[ERROR]', err);

  const statusCode = err.status ?? err.statusCode ?? 500;

  res.status(statusCode).json({
    error: process.env.NODE_ENV === 'production'
      ? 'An unexpected error occurred.'  // Opaque message in production
      : err.message,                     // Detailed message in development only
  });
});

// ---------------------------------------------------------------------------
// Start server
// ---------------------------------------------------------------------------
const PORT = parseInt(process.env.PORT ?? '3000', 10);

// Only start listening when this file is run directly, not when imported by tests
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

