// Simple application — security-hardened version
'use strict';

const express = require('express');

// -- Security middleware (install via npm: helmet, express-rate-limit) --
// const helmet = require('helmet');
// const rateLimit = require('express-rate-limit');

const app = express();

// -------------------------------------------------------------------------
// 1. SECURITY HEADERS
//    Uncomment once 'helmet' is installed (`npm install helmet`).
//    Helmet sets headers like X-Content-Type-Options, X-Frame-Options,
//    Strict-Transport-Security, etc.
// -------------------------------------------------------------------------
// app.use(helmet());

// -------------------------------------------------------------------------
// 2. RATE LIMITING
//    Uncomment once 'express-rate-limit' is installed.
//    Protects all routes from brute-force and DoS request flooding.
// -------------------------------------------------------------------------
// const limiter = rateLimit({
//   windowMs: 15 * 60 * 1000, // 15 minutes
//   max: 100,                  // limit each IP to 100 requests per window
//   standardHeaders: true,
//   legacyHeaders: false,
// });
// app.use(limiter);

// -------------------------------------------------------------------------
// 3. BODY PARSING WITH SIZE LIMITS
//    Prevents excessively large payloads from exhausting server memory.
// -------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// -------------------------------------------------------------------------
// ROUTES
// -------------------------------------------------------------------------

// Health check — no user input, low risk
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users list — includes query-param validation example for future extension
app.get('/users', (req, res, next) => {
  try {
    // Example input validation: reject unexpected query parameters
    const allowedParams = new Set(['page', 'limit']);
    const receivedParams = Object.keys(req.query);
    const invalidParams = receivedParams.filter((p) => !allowedParams.has(p));

    if (invalidParams.length > 0) {
      // 400 Bad Request — do NOT echo back raw user input in the message
      return res.status(400).json({
        error: 'Bad Request',
        message: 'One or more query parameters are not permitted.',
      });
    }

    // Validate and sanitize pagination params if provided
    const page = parseInt(req.query.page, 10);
    const limit = parseInt(req.query.limit, 10);

    if (req.query.page !== undefined && (isNaN(page) || page < 1)) {
      return res.status(400).json({ error: 'Bad Request', message: "'page' must be a positive integer." });
    }
    if (req.query.limit !== undefined && (isNaN(limit) || limit < 1 || limit > 100)) {
      return res.status(400).json({ error: 'Bad Request', message: "'limit' must be an integer between 1 and 100." });
    }

    // Static data — in a real app this would come from a DB call wrapped in try/catch
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users);
  } catch (err) {
    // Pass unexpected errors to the global error handler
    next(err);
  }
});

// -------------------------------------------------------------------------
// 4. 404 HANDLER — catches requests to undefined routes
// -------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found', message: 'The requested resource does not exist.' });
});

// -------------------------------------------------------------------------
// 5. GLOBAL ERROR HANDLER
//    Must have exactly 4 parameters so Express recognises it as an error handler.
//    NEVER expose err.stack or internal details to the client in production.
// -------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  const isDev = process.env.NODE_ENV === 'development';

  // Log the full error server-side for diagnostics
  console.error('[Error]', err);

  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    // Only surface stack traces in development — never in production
    ...(isDev && { detail: err.message, stack: err.stack }),
  });
});

// -------------------------------------------------------------------------
// 6. READ PORT FROM ENVIRONMENT — avoids hardcoding
// -------------------------------------------------------------------------
const PORT = parseInt(process.env.PORT, 10) || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} [${process.env.NODE_ENV || 'development'}]`);
});

// -------------------------------------------------------------------------
// 7. GRACEFUL SHUTDOWN — prevents abrupt connection drops
// -------------------------------------------------------------------------
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Closing HTTP server gracefully...');
  server.close(() => {
    console.log('HTTP server closed.');
    process.exit(0);
  });
});

module.exports = app;

