// Improvements: input validation, error handling, security headers, rate limiting

'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ─── 1. SECURITY HEADERS ────────────────────────────────────────────────────
// helmet sets many protective HTTP headers automatically (e.g. X-Content-Type-Options,
// X-Frame-Options, Strict-Transport-Security, etc.)
app.use(helmet());

// ─── 2. BODY PARSING WITH SIZE LIMIT ────────────────────────────────────────
// Limit payload size to prevent large-body DoS attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ─── 3. RATE LIMITING ───────────────────────────────────────────────────────
// Prevent brute-force and DoS by limiting repeated requests from the same IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // max 100 requests per window per IP
  standardHeaders: true,     // return rate-limit info in RateLimit-* headers
  legacyHeaders: false,
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(limiter);

// ─── 4. HEALTH CHECK ────────────────────────────────────────────────────────
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ─── 5. USERS ENDPOINT WITH INPUT VALIDATION ────────────────────────────────
// Mock data (in production this would come from a database)
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

app.get('/users', (req, res, next) => {
  try {
    const { id } = req.query;

    // If an `id` query param is provided, validate and filter
    if (id !== undefined) {
      const parsedId = parseInt(id, 10);

      // Reject non-integer or non-positive values
      if (!Number.isInteger(parsedId) || parsedId <= 0) {
        return res.status(400).json({ error: 'Invalid id: must be a positive integer.' });
      }

      const user = USERS.find((u) => u.id === parsedId);
      if (!user) {
        return res.status(404).json({ error: 'User not found.' });
      }

      return res.json(user);
    }

    // Return all users (add authentication/authorisation middleware in production)
    res.json(USERS);
  } catch (err) {
    // Forward unexpected errors to the central error handler
    next(err);
  }
});

// ─── 6. 404 HANDLER FOR UNKNOWN ROUTES ──────────────────────────────────────
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ─── 7. CENTRALISED ERROR HANDLING MIDDLEWARE ────────────────────────────────
// Must have exactly 4 parameters so Express recognises it as an error handler
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error server-side (use a proper logger like Winston/Pino in production)
  console.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString(),
  });

  // Never leak internal error details to the client
  const statusCode = err.status || err.statusCode || 500;
  res.status(statusCode).json({
    error: statusCode === 500 ? 'An internal server error occurred.' : err.message,
  });
});

// ─── 8. START SERVER WITH ENV-CONFIGURABLE PORT ─────────────────────────────
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

