// Simple application with security best practices applied
'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// 1. Security headers (helmet sets X-Frame-Options, X-Content-Type-Options,
//    Strict-Transport-Security, Content-Security-Policy, etc.)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. Body parsing — restrict payload size to prevent large-body DoS attacks
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. Rate limiting — 100 requests per 15 minutes per IP across all routes
// ---------------------------------------------------------------------------
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in `RateLimit-*` headers
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(globalLimiter);

// ---------------------------------------------------------------------------
// 4. Basic request logger (replace with a proper logger like `morgan`/`pino`
//    in production — never log sensitive fields such as passwords or tokens)
// ---------------------------------------------------------------------------
app.use((req, _res, next) => {
  const { method, path, ip } = req;
  console.log(`[${new Date().toISOString()}] ${method} ${path} — ${ip}`);
  next();
});

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// Health check — intentionally lean, no sensitive data
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users — add authentication/authorisation middleware before shipping to prod
app.get('/users', (_req, res) => {
  // TODO: replace static data with a real data-access layer and protect this
  //       route with an auth middleware (e.g. JWT verification) so that PII
  //       such as email addresses is never exposed to unauthenticated callers.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

// ---------------------------------------------------------------------------
// 5. 404 handler — catches requests to undefined routes
// ---------------------------------------------------------------------------
app.use((_req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ---------------------------------------------------------------------------
// 6. Global error handler — MUST have four parameters so Express recognises
//    it as an error-handling middleware.
//    Never send stack traces to the client in production.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  console.error(`[${new Date().toISOString()}] Unhandled error:`, err);

  const statusCode = typeof err.status === 'number' ? err.status : 500;
  const message =
    process.env.NODE_ENV === 'production'
      ? 'An unexpected error occurred.'
      : err.message;

  res.status(statusCode).json({ error: message });
});

// ---------------------------------------------------------------------------
// 7. Start server only when this module is the entry point, not when it is
//    required by tests (prevents port conflicts during unit testing)
// ---------------------------------------------------------------------------
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

