// Routes
// ---------------------------------------------------------------------------

// Health check — intentionally minimal; do NOT expose version/env details.
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users list — example of omitting sensitive fields (e.g. email) from the
// response and validating any query parameters before use.
app.get('/users', (req, res, next) => {
  try {
    // Input validation: reject unexpected query parameters early.
    const allowedParams = new Set(['page', 'limit']);
    const receivedParams = Object.keys(req.query);
    const unexpected = receivedParams.filter((p) => !allowedParams.has(p));
    if (unexpected.length > 0) {
      return res.status(400).json({
        error: `Unexpected query parameter(s): ${unexpected.join(', ')}`,
      });
    }

    // Validate and sanitize pagination parameters.
    const page  = parsePositiveInt(req.query.page,  1);
    const limit = parsePositiveInt(req.query.limit, 10);

    if (!page || !limit || limit > 100) {
      return res.status(400).json({
        error: '`page` and `limit` must be positive integers; `limit` ≤ 100.',
      });
    }

    // NOTE: In a real app, query your database here using parameterised queries.
    // Emails and other PII are intentionally omitted from the public response.
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob'   },
    ];

    res.json({ page, limit, total: users.length, data: users });
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler.
  }
});

// ---------------------------------------------------------------------------
// 4. Catch-all for undefined routes (404).
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

