//    Never leak stack traces or internal details to the client.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error server-side for debugging.
  console.error('[Unhandled Error]', err);

  // Respond with a generic message — never expose err.message or err.stack
  // to the client in production, as these can reveal implementation details.
  const statusCode = Number.isInteger(err.status) ? err.status : 500;
  res.status(statusCode).json({ error: 'An unexpected error occurred.' });
});

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Parses a string as a positive integer.
 * Returns `defaultValue` when the input is undefined/null,
 * or `null` when the input is present but invalid.
 *
 * @param {string|undefined} value
 * @param {number}           defaultValue
 * @returns {number|null}
 */
function parsePositiveInt(value, defaultValue) {
  if (value === undefined || value === null) return defaultValue;
  const parsed = Number(value);
  if (!Number.isInteger(parsed) || parsed < 1) return null;
  return parsed;
}

// ---------------------------------------------------------------------------
// Server startup
// ---------------------------------------------------------------------------

// 6. Read port from the environment so the same artifact works in every
//    deployment target without code changes.
const PORT = parseInt(process.env.PORT, 10) || 3000;

app.listen(PORT, () => {
  // Avoid logging environment/config details that could aid an attacker.
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

