'use strict';

// ------------------------------------------------------------
// Dependencies
// npm install express helmet express-rate-limit
// ------------------------------------------------------------
const express = require('express');
const helmet  = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ------------------------------------------------------------
// Configuration — never hardcode; read from environment
// ------------------------------------------------------------
const PORT = parseInt(process.env.PORT, 10) || 3000;

if (!Number.isInteger(PORT) || PORT < 1 || PORT > 65535) {
  console.error(`Invalid PORT value: ${process.env.PORT}`);
  process.exit(1);
}

// ------------------------------------------------------------
// Security middleware
// ------------------------------------------------------------

// Sets X-Content-Type-Options, X-Frame-Options, HSTS, CSP, etc.
app.use(helmet());

// Limit request body size to prevent payload-based DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// Global rate limiter: max 100 requests per 15 minutes per IP
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,   // Return rate limit info in RateLimit-* headers
  legacyHeaders: false,     // Disable X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(globalLimiter);

// ------------------------------------------------------------
// Input validation helper
// ------------------------------------------------------------

/**
 * Validates and sanitises a pagination/filter query object.
 * Returns { valid: true, params } or { valid: false, error }.
 */
function validateUserQueryParams(query) {
  const { page, limit } = query;

  const parsedPage  = page  !== undefined ? parseInt(page,  10) : 1;
  const parsedLimit = limit !== undefined ? parseInt(limit, 10) : 10;

  if (!Number.isInteger(parsedPage)  || parsedPage  < 1) {
    return { valid: false, error: '`page` must be a positive integer.' };
  }
  if (!Number.isInteger(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
    return { valid: false, error: '`limit` must be an integer between 1 and 100.' };
  }

  return { valid: true, params: { page: parsedPage, limit: parsedLimit } };
}

// ------------------------------------------------------------
// Routes
// ------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res, next) => {
  // Validate query parameters before processing
  const { valid, params, error } = validateUserQueryParams(req.query);
  if (!valid) {
    // 400 Bad Request — do not expose internal detail beyond the validation message
    return res.status(400).json({ error });
  }

  // In a real app, `params` (page/limit) would be passed to a DB query.
  // Placeholder data shown here; replace with a parameterised DB call.
  const users = [
    { id: 1, name: 'Alice' },  // ⚠️  Never return passwords, tokens, or
    { id: 2, name: 'Bob'   },  //     unnecessary PII (e.g. raw emails) in list responses.
  ];

  res.json({ page: params.page, limit: params.limit, data: users });
});

// ------------------------------------------------------------
// 404 handler — catches requests to undefined routes
// ------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Not found.' });
});

// ------------------------------------------------------------
// Global error handler — MUST have 4 parameters for Express to
// recognise it as an error-handling middleware.
// ------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error internally (use a proper logger in production)
  console.error(`[${new Date().toISOString()}] Unhandled error:`, err);

  // Never leak stack traces or internal error messages to clients
  const statusCode = Number.isInteger(err.status) ? err.status : 500;
  res.status(statusCode).json({ error: 'An unexpected error occurred.' });
});

// ------------------------------------------------------------
// Start server
// ------------------------------------------------------------
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

