// app.js — Secure Express application
'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ---------------------------------------------------------------------------
// 1. Security Headers (helmet sets X-Frame-Options, X-Content-Type-Options,
//    Content-Security-Policy, and more out of the box)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. Body parsing — enforce a strict size limit to prevent large-payload DoS
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. Global rate limiter — 100 requests per 15 minutes per IP
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in `RateLimit-*` headers
  legacyHeaders: false,   // Disable the `X-RateLimit-*` headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// 4. Input validation helper
//    Centralising validation logic makes it easy to test and reuse.
// ---------------------------------------------------------------------------

/**
 * Validates that a value is a safe positive integer string.
 * Rejects anything that is not a finite positive whole number.
 * @param {string} value
 * @returns {number|null}  Parsed integer, or null if invalid.
 */
function parsePositiveInt(value) {
  if (value === undefined || value === null) return null;
  // Only allow strings of digits (no leading zeros, no floats, no negatives)
  if (!/^\d+$/.test(String(value))) return null;
  const n = Number(value);
  if (!Number.isFinite(n) || n <= 0 || n > Number.MAX_SAFE_INTEGER) return null;
  return n;
}

/**
 * Validates that a string contains only safe alphanumeric/space/hyphen chars.
 * Guards against injection via name-based lookups.
 * @param {string} value
 * @param {number} maxLength
 * @returns {string|null}  Sanitised string, or null if invalid.
 */
function parseSafeName(value, maxLength = 100) {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  if (trimmed.length === 0 || trimmed.length > maxLength) return null;
  // Allow letters, digits, spaces, hyphens, apostrophes — reject everything else
  if (!/^[\w\s'\-]+$/u.test(trimmed)) return null;
  return trimmed;
}

// ---------------------------------------------------------------------------
// 5. Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res, next) => {
  try {
    // Example of validated optional query params — extend as your data layer grows
    const { id, name } = req.query;

    if (id !== undefined) {
      const parsedId = parsePositiveInt(id);
      if (parsedId === null) {
        return res.status(400).json({
          error: 'Invalid parameter: "id" must be a positive integer.',
        });
      }
    }

    if (name !== undefined) {
      const parsedName = parseSafeName(name);
      if (parsedName === null) {
        return res.status(400).json({
          error: 'Invalid parameter: "name" must be 1–100 safe characters.',
        });
      }
    }

    // Static data kept for illustration; replace with a parameterised DB query
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users);
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler
  }
});

// ---------------------------------------------------------------------------
// 6. 404 handler — catches requests to undefined routes
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Not found.' });
});

// ---------------------------------------------------------------------------
// 7. Global error handler
//    Must have exactly four parameters so Express recognises it as an error
//    handler.  Stack traces are logged server-side but NEVER sent to clients.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error internally (replace with your structured logger)
  console.error({
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method,
  });

  // Return a generic message — never expose internals to the client
  const status = err.status ?? err.statusCode ?? 500;
  res.status(status).json({ error: 'An unexpected error occurred.' });
});

// ---------------------------------------------------------------------------
// 8. Port configuration — read from environment, fall back to 3000
// ---------------------------------------------------------------------------
const PORT = Number(process.env.PORT) || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// ---------------------------------------------------------------------------
// 9. Graceful shutdown — avoids abrupt connection drops in production
// ---------------------------------------------------------------------------
function shutdown(signal) {
  console.log(`Received ${signal}. Shutting down gracefully…`);
  server.close(() => {
    console.log('HTTP server closed.');
    process.exit(0);
  });

  // Force-exit if shutdown takes longer than 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout.');
    process.exit(1);
  }, 10_000);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

module.exports = app;

