'use strict';

const express = require('express');
const helmet = require('helmet');           // Secure HTTP headers
const rateLimit = require('express-rate-limit'); // Rate limiting

const app = express();

// ──────────────────────────────────────────────
// 1. SECURITY HEADERS
//    helmet sets a safe baseline of HTTP headers
//    (X-Frame-Options, X-Content-Type-Options, etc.)
// ──────────────────────────────────────────────
app.use(helmet());

// ──────────────────────────────────────────────
// 2. REQUEST BODY PARSING WITH SIZE LIMIT
//    Prevents large-payload denial-of-service attacks.
// ──────────────────────────────────────────────
app.use(express.json({ limit: '10kb' }));

// ──────────────────────────────────────────────
// 3. RATE LIMITING
//    Limits each IP to 100 requests per 15 minutes
//    to mitigate brute-force and DoS attacks.
// ──────────────────────────────────────────────
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,    // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,     // Disable X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ──────────────────────────────────────────────
// MOCK DATA (replace with real DB calls in production)
// ──────────────────────────────────────────────
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ──────────────────────────────────────────────
// HELPER: Shape a user object for API responses.
//   Explicitly allowlist fields to prevent accidental
//   exposure of sensitive properties (e.g., passwords,
//   tokens) if the underlying model grows over time.
// ──────────────────────────────────────────────
function sanitizeUser(user) {
  return {
    id:    user.id,
    name:  user.name,
    email: user.email,
  };
}

// ──────────────────────────────────────────────
// ROUTES
// ──────────────────────────────────────────────

// GET /health
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// GET /users
//   Supports optional query params: ?name=<string>&page=<int>&limit=<int>
app.get('/users', (req, res, next) => {
  try {
    const { name, page: rawPage, limit: rawLimit } = req.query;

    // -- Input validation --

    // `name` filter: only allow safe characters (letters, spaces, hyphens)
    if (name !== undefined) {
      if (typeof name !== 'string' || !/^[a-zA-Z\s\-]{1,100}$/.test(name)) {
        return res.status(400).json({
          error: 'Invalid "name" parameter. Use letters, spaces, or hyphens (max 100 chars).',
        });
      }
    }

    // `page` must be a positive integer, defaulting to 1
    const page = rawPage !== undefined ? parseInt(rawPage, 10) : 1;
    if (!Number.isInteger(page) || page < 1 || page > 10_000) {
      return res.status(400).json({ error: 'Invalid "page" parameter. Must be a positive integer.' });
    }

    // `limit` must be between 1 and 100, defaulting to 20
    const limit = rawLimit !== undefined ? parseInt(rawLimit, 10) : 20;
    if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({ error: 'Invalid "limit" parameter. Must be between 1 and 100.' });
    }

    // -- Business logic --
    let results = USERS;

    if (name) {
      const lowerName = name.toLowerCase();
      results = results.filter((u) => u.name.toLowerCase().includes(lowerName));
    }

    const start       = (page - 1) * limit;
    const paginated   = results.slice(start, start + limit);
    const sanitized   = paginated.map(sanitizeUser);

    res.json({
      data:  sanitized,
      meta: {
        page,
        limit,
        total: results.length,
      },
    });
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler
  }
});

// ──────────────────────────────────────────────
// 4. 404 HANDLER
//    Catches requests to undefined routes and returns
//    JSON instead of Express's default HTML response,
//    which would leak framework/version information.
// ──────────────────────────────────────────────
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ──────────────────────────────────────────────
// 5. GLOBAL ERROR HANDLER
//    Must have exactly 4 parameters for Express to
//    recognise it as an error-handling middleware.
//    Prevents stack traces from leaking to clients.
// ──────────────────────────────────────────────
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error('[Unhandled error]', err); // Log internally for diagnostics

  const statusCode = typeof err.status === 'number' ? err.status : 500;

  res.status(statusCode).json({
    error: statusCode === 500
      ? 'An unexpected error occurred. Please try again later.' // Never expose internals
      : err.message,
  });
});

// ──────────────────────────────────────────────
// 6. SERVER STARTUP
//    Read port from environment; fall back to 3000
//    for local development only.
// ──────────────────────────────────────────────
const PORT = process.env.PORT || 3000;

// Only start the server when this file is run directly,
// not when it is required by tests.
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

