'use strict';

const express = require('express');
const helmet = require('helmet');         // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting

const app = express();

// ─── 1. SECURITY HEADERS ────────────────────────────────────────────────────
// helmet sets several HTTP headers to protect against well-known web
// vulnerabilities (XSS, clickjacking, MIME sniffing, etc.)
app.use(helmet());

// ─── 2. REQUEST BODY PARSING WITH SIZE LIMITS ───────────────────────────────
// Limit payload size to prevent large-body DoS attacks.
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ─── 3. RATE LIMITING ───────────────────────────────────────────────────────
// Restrict each IP to 100 requests per 15-minute window.
// Adjust windowMs / max to suit your traffic expectations.
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,   // Disable X-RateLimit-* headers
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(limiter);

// ─── 4. CORS POLICY ─────────────────────────────────────────────────────────
// Define explicitly which origins are allowed.
// Avoid using '*' in production — it permits any origin to call your API.
const ALLOWED_ORIGINS = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');

app.use((req, res, next) => {
  const origin = req.headers.origin;
  if (origin && ALLOWED_ORIGINS.includes(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);
  }
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  if (req.method === 'OPTIONS') return res.sendStatus(204);
  next();
});

// ─── 5. HEALTH ENDPOINT ─────────────────────────────────────────────────────
// No sensitive internal details (versions, hostnames, etc.) in health responses.
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ─── 6. USERS ENDPOINT WITH INPUT VALIDATION ────────────────────────────────
// Even for read-only endpoints, validate and sanitize any query parameters
// to prevent injection attacks and unexpected behaviour.

/**
 * Validates that a value is a safe, positive integer.
 * Returns the parsed integer, or null if invalid.
 */
function parsePositiveInt(value) {
  if (value === undefined || value === null) return null;
  const parsed = parseInt(value, 10);
  // Reject NaN, floats-as-strings ('1.5'), negative numbers, and non-numeric strings
  if (isNaN(parsed) || String(parsed) !== String(value) || parsed < 1) return null;
  return parsed;
}

// Simulated user data — in production this would come from a database.
// Never expose sensitive fields (passwords, tokens, SSNs) in list responses.
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// GET /users          — returns all users
// GET /users?id=1     — returns a single user by id
app.get('/users', (req, res, next) => {
  try {
    const { id } = req.query;

    // If an id query param was provided, validate and filter
    if (id !== undefined) {
      const userId = parsePositiveInt(id);
      if (userId === null) {
        // 400 Bad Request — invalid input; do NOT echo raw input back
        return res.status(400).json({ error: 'Invalid id parameter. Must be a positive integer.' });
      }

      const user = USERS.find((u) => u.id === userId);
      if (!user) {
        return res.status(404).json({ error: 'User not found.' });
      }
      return res.json(user);
    }

    // No filter — return all users
    res.json(USERS);
  } catch (err) {
    // Pass unexpected errors to the central error handler below
    next(err);
  }
});

// ─── 7. 404 HANDLER ─────────────────────────────────────────────────────────
// Catch requests to undefined routes before they reach the error handler.
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ─── 8. CENTRALISED ERROR HANDLER ───────────────────────────────────────────
// Must have exactly four parameters so Express recognises it as an error handler.
// NEVER send stack traces or internal error details to the client in production —
// they can reveal implementation details useful to an attacker.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error('[ERROR]', err); // Log full details server-side only

  const statusCode = typeof err.status === 'number' ? err.status : 500;
  res.status(statusCode).json({
    error: process.env.NODE_ENV === 'production'
      ? 'An unexpected error occurred.'  // Generic message for production
      : err.message,                     // More detail during development
  });
});

// ─── 9. SAFE SERVER STARTUP ──────────────────────────────────────────────────
// Read port from the environment so it can vary across deployments without
// code changes, and to avoid hardcoding privileged port numbers.
const PORT = parseInt(process.env.PORT || '3000', 10);

if (isNaN(PORT) || PORT < 1 || PORT > 65535) {
  console.error('Invalid PORT environment variable. Must be a number between 1 and 65535.');
  process.exit(1);
}

// Only start listening when this file is run directly (not when imported by tests).
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

