'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ---------------------------------------------------------------------------
// 1. Security headers (helmet sets X-Frame-Options, HSTS, nosniff, etc.)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. Body parsing with a strict size limit to prevent DoS via large payloads
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. Rate limiting — applies to all routes
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // max 100 requests per window per IP
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// 4. Routes
// ---------------------------------------------------------------------------
app.get('/health', (req, res) => {
  // Deliberately minimal response — don't expose version, hostname, etc.
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res, next) => {
  try {
    // Input validation example: reject unexpected query parameters
    const allowedParams = new Set(['page', 'limit']);
    const receivedParams = Object.keys(req.query);
    const unexpected = receivedParams.filter((p) => !allowedParams.has(p));

    if (unexpected.length > 0) {
      return res.status(400).json({
        error: 'Invalid query parameters.',
        // Do NOT echo back the unexpected values themselves to avoid reflected injection
      });
    }

    // Validate and sanitise pagination params
    const page = parseInt(req.query.page, 10) || 1;
    const limit = parseInt(req.query.limit, 10) || 10;

    if (page < 1 || limit < 1 || limit > 100) {
      return res.status(400).json({ error: 'Invalid pagination parameters.' });
    }

    // Static data shown here; in a real app this would be a DB call wrapped in try/catch
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    return res.json({ data: users, page, limit });
  } catch (err) {
    return next(err); // delegate to the global error handler below
  }
});

// ---------------------------------------------------------------------------
// 5. 404 handler — must come after all valid routes
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Not found.' });
});

// ---------------------------------------------------------------------------
// 6. Global error handler — 4-argument signature is required by Express
//    Never send stack traces or internal details to the client.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error internally (replace with your logger, e.g. winston/pino)
  console.error('[Unhandled error]', err);

  // Return a generic message; never leak err.message or err.stack to clients
  res.status(500).json({ error: 'An internal server error occurred.' });
});

// ---------------------------------------------------------------------------
// 7. Process-level safety nets
// ---------------------------------------------------------------------------
process.on('unhandledRejection', (reason) => {
  // Log and let the process exit so a process manager (e.g. PM2) can restart it
  console.error('[unhandledRejection]', reason);
  process.exit(1);
});

process.on('uncaughtException', (err) => {
  console.error('[uncaughtException]', err);
  process.exit(1);
});

// ---------------------------------------------------------------------------
// 8. Configurable port via environment variable, with a safe default
// ---------------------------------------------------------------------------
const PORT = parseInt(process.env.PORT, 10) || 3000;

app.listen(PORT, () => {
  // Avoid logging sensitive config details in production
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

