// [FIX #9] Centralised validation — extend with joi/zod for complex schemas
function validatePositiveInteger(value, fieldName) {
  const num = Number(value);
  if (!Number.isInteger(num) || num < 1) {
    throw Object.assign(new Error(`Invalid ${fieldName}: must be a positive integer`), {
      status: 400,
    });
  }
  return num;
}

// ─── Routes ───────────────────────────────────────────────────────────────────

