  const message =
    process.env.NODE_ENV === 'production' && status === 500
      ? 'Internal server error'
      : err.message;

  // Log the full error server-side
  console.error(`[ERROR] ${err.stack || err}`);

  res.status(status).json({ error: message });
});

// ─── Start ────────────────────────────────────────────────────────────────────

