// Simple application with security best practices applied
// Dependencies: express, helmet, express-rate-limit, morgan
// Install: npm install express helmet express-rate-limit morgan

'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

// ─── Security Headers ────────────────────────────────────────────────────────
// Sets X-Content-Type-Options, X-Frame-Options, HSTS, and more.
app.use(helmet());

// ─── Request Logging ─────────────────────────────────────────────────────────
// 'combined' format provides IP, method, path, status, and user-agent.
// In production, pipe this to a log aggregator instead of stdout.
app.use(morgan('combined'));

// ─── Body Parsing with Size Limit ────────────────────────────────────────────
// Prevents excessively large payloads from being processed (e.g., DoS via body size).
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ─── Rate Limiting ───────────────────────────────────────────────────────────
// Protects all routes from brute-force and abuse.
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // Max 100 requests per window per IP
  standardHeaders: true,     // Return rate limit info in RateLimit-* headers
  legacyHeaders: false,      // Disable X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ─── Routes ──────────────────────────────────────────────────────────────────

// Health check — intentionally public, no sensitive data exposed
app.get('/health', (req, res) => {
  res.status(200).json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint — returns PII (emails), should be protected by auth middleware.
// TODO: Add authentication/authorization middleware before this handler.
// Example: app.get('/users', requireAuth, (req, res) => { ... })
app.get('/users', (req, res) => {
  // TODO: Replace with a real database query; never expose raw DB errors to clients.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.status(200).json(users);
});

// ─── 404 Handler ─────────────────────────────────────────────────────────────
// Catches requests to undefined routes; avoids leaking framework details.
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ─── Global Error Handler ────────────────────────────────────────────────────
// Catches errors passed via next(err) or thrown in async handlers.
// IMPORTANT: Never send stack traces or internal details to the client in production.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error internally for debugging
  console.error(`[${new Date().toISOString()}] Unhandled error:`, err);

  const statusCode = err.status || err.statusCode || 500;
  const isProd = process.env.NODE_ENV === 'production';

  res.status(statusCode).json({
    error: isProd ? 'An unexpected error occurred.' : err.message,
  });
});

// ─── Server Bootstrap ────────────────────────────────────────────────────────
// Use environment variable for port; fall back to 3000 for local development.
const PORT = parseInt(process.env.PORT, 10) || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} [${process.env.NODE_ENV || 'development'}]`);
});

// Graceful shutdown: allow in-flight requests to complete before exiting.
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed.');
    process.exit(0);
  });
});

module.exports = app;

