/**
 * app.js — Express application with security best practices applied.
 *
 * Dependencies to install:
 *   npm install helmet express-rate-limit cors
 */

'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// ---------------------------------------------------------------------------
// 1. Security Headers (helmet sets ~15 protective HTTP headers automatically)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. CORS — restrict origins explicitly; update ALLOWED_ORIGIN in production
// ---------------------------------------------------------------------------
const ALLOWED_ORIGIN = process.env.ALLOWED_ORIGIN || 'http://localhost:3000';
app.use(
  cors({
    origin: ALLOWED_ORIGIN,
    methods: ['GET'],          // Only expose the HTTP verbs this API uses
    allowedHeaders: ['Content-Type'],
  })
);

// ---------------------------------------------------------------------------
// 3. Body parsing with a strict size limit to prevent large-payload DoS
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 4. Global rate limiter — 100 requests per 15 minutes per IP
// ---------------------------------------------------------------------------
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,   // Return RateLimit-* headers (RFC 6585)
  legacyHeaders: false,    // Disable deprecated X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(globalLimiter);

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// Health check — intentionally not rate-limited further (load balancers need it)
app.get('/health', (req, res) => {
  // Do NOT expose implementation details (versions, env, etc.) here
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users list — tighter rate limit on data-returning endpoints
const usersLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 30,
  message: { error: 'Too many requests to /users, please slow down.' },
});

app.get('/users', usersLimiter, (req, res) => {
  // Input validation example: optional ?limit query param
  const rawLimit = req.query.limit;
  let limit;

  if (rawLimit !== undefined) {
    limit = parseInt(rawLimit, 10);
    // Reject non-integer or out-of-range values
    if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Invalid "limit" parameter. Must be an integer between 1 and 100.',
      });
    }
  }

  // In a real app this data would come from a database; mocked here for clarity
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const result = limit ? users.slice(0, limit) : users;
  res.json(result);
});

// ---------------------------------------------------------------------------
// 5. 404 handler — catches all unmatched routes without leaking framework info
// ---------------------------------------------------------------------------
app.use((_req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ---------------------------------------------------------------------------
// 6. Global error handler — must have exactly 4 params so Express recognises it
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  // Log internally with full detail; never send stack traces to the client
  console.error('Unhandled error:', err);
  res.status(500).json({ error: 'An unexpected error occurred.' });
});

// ---------------------------------------------------------------------------
// 7. Start server only when this file is run directly, not when it is imported
//    (e.g. by a test suite via require('./app'))
// ---------------------------------------------------------------------------
if (require.main === module) {
  const PORT = parseInt(process.env.PORT || '3000', 10);
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

