// Simple application — hardened for security best practices

'use strict';

const express = require('express');

const app = express();

// ---------------------------------------------------------------------------
// Security: parse JSON bodies with a size limit to prevent payload attacks
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));

// ---------------------------------------------------------------------------
// Security headers — set manually or via `helmet` (npm install helmet)
// ---------------------------------------------------------------------------
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'no-referrer');
  res.removeHeader('X-Powered-By'); // Don't advertise Express
  next();
});

// ---------------------------------------------------------------------------
// Health check — minimal response, no server internals exposed
// ---------------------------------------------------------------------------
app.get('/health', (req, res) => {
  res.status(200).json({ status: 'ok' });
});

// ---------------------------------------------------------------------------
// Users — static list for now; validate any future query parameters strictly
// ---------------------------------------------------------------------------

/** Allowlist of fields that may be used for filtering */
const ALLOWED_FILTER_FIELDS = new Set(['id', 'name']);

const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

app.get('/users', (req, res) => {
  // Reject unexpected query parameters to prevent parameter pollution
  const receivedKeys = Object.keys(req.query);
  const disallowedKeys = receivedKeys.filter((k) => !ALLOWED_FILTER_FIELDS.has(k));

  if (disallowedKeys.length > 0) {
    return res.status(400).json({
      error: 'Bad Request',
      message: `Unknown query parameter(s): ${disallowedKeys.join(', ')}`,
    });
  }

  // Validate `id` if provided — must be a positive integer
  if (req.query.id !== undefined) {
    const id = Number(req.query.id);
    if (!Number.isInteger(id) || id <= 0) {
      return res.status(400).json({
        error: 'Bad Request',
        message: '`id` must be a positive integer',
      });
    }
  }

  // Validate `name` if provided — letters, spaces, hyphens only (max 100 chars)
  if (req.query.name !== undefined) {
    if (!/^[a-zA-Z\s\-]{1,100}$/.test(req.query.name)) {
      return res.status(400).json({
        error: 'Bad Request',
        message: '`name` contains invalid characters or exceeds length limit',
      });
    }
  }

  // Apply optional filters
  let results = USERS;
  if (req.query.id) {
    results = results.filter((u) => u.id === Number(req.query.id));
  }
  if (req.query.name) {
    // Case-insensitive exact match
    const nameLower = req.query.name.toLowerCase();
    results = results.filter((u) => u.name.toLowerCase() === nameLower);
  }

  res.status(200).json(results);
});

// ---------------------------------------------------------------------------
// 404 handler — catch all unmatched routes
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
  });
});

// ---------------------------------------------------------------------------
// Global error handler — never leak stack traces to clients
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error internally (replace with your logger, e.g. winston/pino)
  console.error('[ERROR]', err);

  // Return a safe, generic message to the client
  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    message: 'An unexpected error occurred. Please try again later.',
  });
});

// ---------------------------------------------------------------------------
// Server startup — port from environment variable with a safe fallback
// ---------------------------------------------------------------------------
const PORT = parseInt(process.env.PORT || '3000', 10);

if (isNaN(PORT) || PORT < 1 || PORT > 65535) {
  console.error(`[FATAL] Invalid PORT value: ${process.env.PORT}`);
  process.exit(1);
}

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown on SIGTERM (e.g. from Docker/Kubernetes)
process.on('SIGTERM', () => {
  console.log('SIGTERM received — shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;
